#include "policy.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static struct steer_pv1_span s(const char*x){struct steer_pv1_span v={(const uint8_t*)x,(uint32_t)strlen(x)};return v;}
static struct steer_pv1_error visited(void*arg,const struct steer_policy_rule*r){unsigned*n=arg;assert(r->id.len&&r->action);(*n)++;return (struct steer_pv1_error){0,0};}
int main(void){struct steer_policy_rule r[2]={0};struct steer_policy*p;uint8_t ip[4]={203,0,113,17};struct steer_pv1_endpoint e={sizeof(e),1,1,{ip,4},443,0};struct steer_policy_input stream={7,{0},{0},&e};struct steer_policy_packet_input packet={7,{0},{0},&e,6};struct steer_policy_decision a,b;uint32_t fallback;unsigned count=0,protocol,port;r[0].id=s("port-block");r[0].inbound=s("kernel");r[0].principal=s("alice");r[0].port_first=440;r[0].port_last=450;r[0].action=STEER_POLICY_BLOCK;r[1].id=s("prefix-allow");r[1].cidr_tag=1;r[1].prefix_bits=24;r[1].network[0]=203;r[1].network[2]=113;r[1].action=STEER_POLICY_DIRECT;assert(!steer_policy_compile(7,r,2,STEER_POLICY_BLOCK,&p).code);stream.inbound=packet.inbound=s("kernel");stream.principal=packet.principal=s("alice");for(protocol=6;protocol<=17;protocol+=11)for(port=430;port<460;port++){e.port=(uint16_t)port;packet.ip_protocol=protocol;assert(!steer_policy_evaluate(p,&stream,&a).code&&!steer_policy_packet_evaluate(p,&packet,&b).code);assert(a.action==b.action&&a.rule_index==b.rule_index);}e.port=0;packet.ip_protocol=1;assert(steer_policy_evaluate(p,&stream,&a).code==STEER_PV1_INVALID);assert(!steer_policy_packet_evaluate(p,&packet,&b).code&&b.action==STEER_POLICY_DIRECT&&b.rule_index==1);packet.ip_protocol=58;assert(!steer_policy_packet_evaluate(p,&packet,&b).code&&b.action==STEER_POLICY_DIRECT);packet.ip_protocol=256;assert(steer_policy_packet_evaluate(p,&packet,&b).code==STEER_PV1_INVALID&&b.action==STEER_POLICY_BLOCK);assert(!steer_policy_visit(p,7,visited,&count,&fallback).code&&count==2&&fallback==STEER_POLICY_BLOCK);assert(steer_policy_visit(p,8,visited,&count,&fallback).code==STEER_PV1_POLICY_DENIED);steer_policy_destroy(p);puts("packet policy tests passed");return 0;}
